begin;
with j as (select * from jsonb_to_recordset($law7d0030$[{"code_id":"GK_RF_2","article_number":"1022","version_date":"1994-11-30","article_text":"1. Доверительный управляющий, не проявивший при доверительном управлении имуществом должной заботливости об интересах выгодоприобретателя или учредителя управления, возмещает выгодоприобретателю упущенную выгоду за время доверительного управления имуществом, а учредителю управления убытки, причиненные утратой или повреждением имущества, с учетом его естественного износа, а также упущенную выгоду.\n\nДоверительный управляющий несет ответственность за причиненные убытки, если не докажет, что эти убытки произошли вследствие непреодолимой силы либо действий выгодоприобретателя или учредителя управления.\n\n2. Обязательства по сделке, совершенной доверительным управляющим с превышением предоставленных ему полномочий или с нарушением установленных для него ограничений, несет доверительный управляющий лично. Если участвующие в сделке третьи лица не знали и не должны были знать о превышении полномочий или об установленных ограничениях, возникшие обязательства подлежат исполнению в порядке, установленном пунктом 3 настоящей статьи. Учредитель управления может в этом случае потребовать от доверительного управляющего возмещения понесенных им убытков.\n\n3. Долги по обязательствам, возникшим в связи с доверительным управлением имуществом, погашаются за счет этого имущества. В случае недостаточности этого имущества взыскание может быть обращено на имущество доверительного управляющего, а при недостаточности и его имущества на имущество учредителя управления, не переданное в доверительное управление.\n\n4. Договор доверительного управления имуществом может предусматривать предоставление доверительным управляющим залога в обеспечение возмещения убытков, которые могут быть причинены учредителю управления или выгодоприобретателю ненадлежащим исполнением договора доверительного управления.","article_title":"Статья 1022. Ответственность доверительного управляющего","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a01b9b94aaf1d335421225084e8dac01878cdcce27e8ad17277a1ad7a6ec5682"},{"code_id":"GK_RF_2","article_number":"1023","version_date":"1994-11-30","article_text":"Доверительный управляющий имеет право на вознаграждение, предусмотренное договором доверительного управления имуществом, а также на возмещение необходимых расходов, произведенных им при доверительном управлении имуществом, за счет доходов от использования этого имущества.","article_title":"Статья 1023. Вознаграждение доверительному управляющему","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"295dfe5b68984b8584be46d884dac85d1f6384d13d5931382f85aa8a4f0f1b8d"},{"code_id":"GK_RF_2","article_number":"1024","version_date":"1994-11-30","article_text":"1. Договор доверительного управления имуществом прекращается вследствие:\n\nсмерти гражданина, являющегося выгодоприобретателем, или ликвидации юридического лица - выгодоприобретателя, если договором не предусмотрено иное;\n\nотказа выгодоприобретателя от получения выгод по договору, если договором не предусмотрено иное;\n\nсмерти гражданина, являющегося доверительным управляющим, признания его недееспособным, ограниченно дееспособным или безвестно отсутствующим, а также признания индивидуального предпринимателя несостоятельным (банкротом);\n\nотказа доверительного управляющего или учредителя управления от осуществления доверительного управления в связи с невозможностью для доверительного управляющего лично осуществлять доверительное управление имуществом;\n\nотказа учредителя управления от договора по иным причинам, чем та, которая указана в абзаце пятом настоящего пункта, при условии выплаты доверительному управляющему обусловленного договором вознаграждения;\n\nпризнания несостоятельным (банкротом) гражданина-предпринимателя, являющегося учредителем управления.\n\n2. При отказе одной стороны от договора доверительного управления имуществом другая сторона должна быть уведомлена об этом за три месяца до прекращения договора, если договором не предусмотрен иной срок уведомления.\n\n3. При прекращении договора доверительного управления имущество, находящееся в доверительном управлении, передается учредителю управления, если договором не предусмотрено иное.","article_title":"Статья 1024. Прекращение договора доверительного управления имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8756194a802d6a7cea94a18d96fb190720b1eebbaca53d6d8ed54117b8617bc7"},{"code_id":"GK_RF_2","article_number":"1025","version_date":"1994-11-30","article_text":"При передаче в доверительное управление ценных бумаг может быть предусмотрено объединение ценных бумаг, передаваемых в доверительное управление разными лицами.\n\nПравомочия доверительного управляющего по распоряжению ценными бумагами определяются в договоре доверительного управления.\n\nОсобенности доверительного управления ценными бумагами определяются законом.\n\nа настоящей статьи соответственно применяются к правам, удостоверенным бездокументарными ценными бумагами (статья 149).","article_title":"Статья 1025. Передача в доверительное управление ценных бумаг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"14bf5b17df5a574ab57c8ccf701ed2710e9508fea742e0d8e9312b0575f1ade0"},{"code_id":"GK_RF_2","article_number":"1026","version_date":"1994-11-30","article_text":"1. Доверительное управление имуществом может быть также учреждено:\n\nвследствие необходимости постоянного управления имуществом подопечного в случаях, предусмотренных статьей 38 настоящего Кодекса;\n\nвследствие необходимости управления наследственным имуществом (статья 1173);  (В редакции Федерального закона от 29.07.2017 № 259-ФЗ)\n\nпо иным основаниям, предусмотренным законом.\n\n2. Правила, предусмотренные настоящей главой, соответственно применяются к отношениям по доверительному управлению имуществом, учрежденному по основаниям, указанным в пункте 1 настоящей статьи, если иное не предусмотрено законом и не вытекает из существа таких отношений.\n\nВ случаях, когда доверительное управление имуществом учреждается по основаниям, указанным в пункте 1 настоящей статьи, права учредителя управления, предусмотренные правилами настоящей главы, принадлежат соответственно органу опеки и попечительства, нотариусу или иному лицу, указанному в законе. (В редакции Федерального закона от 29.07.2017 № 259-ФЗ)","article_title":"Статья 1026. Доверительное управление имуществом по основаниям, предусмотренным законом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c857dda82344fe9aceb25a4fc7100bb13758544266d519d3d22c930a57825d0e"},{"code_id":"GK_RF_2","article_number":"1028","version_date":"1994-11-30","article_text":"1. Договор коммерческой концессии должен быть заключен в письменной форме.\n\nНесоблюдение письменной формы договора влечет его недействительность. Такой договор считается ничтожным.","article_title":"Статья 1028. Форма и регистрация договора коммерческой концессии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"02bf234124ca3ff29161b8026ba0cf13ad41ed2efb025b0ffde9253b888b5b3e"},{"code_id":"GK_RF_2","article_number":"1029","version_date":"1994-11-30","article_text":"1. Договором коммерческой концессии может быть предусмотрено право пользователя разрешать другим лицам использование предоставленного ему комплекса исключительных прав или части этого комплекса на условиях субконцессии, согласованных им с правообладателем либо определенных в договоре коммерческой концессии. В договоре может быть предусмотрена обязанность пользователя предоставить в течение определенного срока определенному числу лиц право пользования указанными правами на условиях субконцессии.\n\nДоговор коммерческой субконцессии не может быть заключен на более длительный срок, чем договор коммерческой концессии, на основании которого он заключается.\n\n2. Если договор коммерческой концессии является недействительным, недействительны и заключенные на основании его договоры коммерческой субконцессии.\n\n3. Если иное не предусмотрено договором коммерческой концессии, заключенным на срок, при его досрочном прекращении права и обязанности вторичного правообладателя по договору коммерческой субконцессии (пользователя по договору коммерческой концессии) переходят к правообладателю, если он не откажется от принятия на себя прав и обязанностей по этому договору. Это правило соответственно применяется при расторжении договора коммерческой концессии, заключенного без указания срока.\n\n4. Пользователь несет субсидиарную ответственность за вред, причиненный правообладателю действиями вторичных пользователей, если иное не предусмотрено договором коммерческой концессии.\n\n5. К договору коммерческой субконцессии применяются предусмотренные настоящей главой правила о договоре коммерческой концессии, если иное не вытекает из особенностей субконцессии.","article_title":"Статья 1029. Коммерческая субконцессия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77e6ea56f4311cc3c0421db921599385aa6ce1a65cee4a035cc8865b8161788a"},{"code_id":"GK_RF_2","article_number":"1030","version_date":"1994-11-30","article_text":"Вознаграждение по договору коммерческой концессии может выплачиваться пользователем правообладателю в форме фиксированных разовых и (или) периодических платежей, отчислений от выручки, наценки на оптовую цену товаров, передаваемых правообладателем для перепродажи, или в иной форме, предусмотренной договором. (В редакции Федерального закона от 18.07.2011 № 216-ФЗ)","article_title":"Статья 1030. Вознаграждение по договору коммерческой концессии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57e184c75081ad8052331348b9ad8d335f669b2c17c969a72979e41ad9115a36"},{"code_id":"GK_RF_2","article_number":"1031","version_date":"1994-11-30","article_text":"обеспечить государственную регистрацию предоставления права использования в предпринимательской деятельности пользователя комплекса принадлежащих правообладателю исключительных прав по договору коммерческой концессии (пункт 2 статьи 1028); (В редакции федеральных законов от 18.12.2006 № 231-ФЗ; от 12.03.2014 № 35-ФЗ)\n\nоказывать пользователю постоянное техническое и консультативное содействие, включая содействие в обучении и повышении квалификации работников;\n\nконтролировать качество товаров (работ, услуг), производимых (выполняемых, оказываемых) пользователем на основании договора коммерческой концессии.","article_title":"Статья 1031. Обязанности правообладателя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"28ae344d6dfa932c8a97b59bd64ea7476b3427dee78400abfbb1cca9a1922778"},{"code_id":"GK_RF_2","article_number":"1032","version_date":"1994-11-30","article_text":"С учетом характера и особенностей деятельности, осуществляемой пользователем по договору коммерческой концессии, пользователь обязан:\n\nиспользовать при осуществлении предусмотренной договором деятельности коммерческое обозначение, товарный знак, знак обслуживания или иное средство индивидуализации правообладателя указанным в договоре образом; (В редакции Федерального закона от 18.12.2006 № 231-ФЗ)\n\nобеспечивать соответствие качества производимых им на основе договора товаров, выполняемых работ, оказываемых услуг качеству аналогичных товаров, работ или услуг, производимых, выполняемых или оказываемых непосредственно правообладателем;\n\nсоблюдать инструкции и указания правообладателя, направленные на обеспечение соответствия характера, способов и условий использования комплекса исключительных прав тому, как он используется правообладателем, в том числе указания, касающиеся внешнего и внутреннего оформления коммерческих помещений, используемых пользователем при осуществлении предоставленных ему по договору прав;\n\nоказывать покупателям (заказчикам) все дополнительные услуги, на которые они могли бы рассчитывать, приобретая (заказывая) товар (работу, услугу) непосредственно у правообладателя;\n\nне разглашать секреты производства (ноу-хау) правообладателя и другую полученную от него конфиденциальную коммерческую информацию; (В редакции Федерального закона от 18.12.2006 № 231-ФЗ)\n\nпредоставить оговоренное количество субконцессий, если такая обязанность предусмотрена договором;\n\nинформировать покупателей (заказчиков) наиболее очевидным для них способом о том, что он использует коммерческое обозначение, товарный знак, знак обслуживания или иное средство индивидуализации в силу договора коммерческой концессии. (В редакции Федерального закона от 18.12.2006 № 231-ФЗ)","article_title":"Статья 1032. Обязанности пользователя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"19a51026b60ed1761443e82a65cd9b30658a70b34df591ed332c46a51c045f99"},{"code_id":"GK_RF_2","article_number":"1033","version_date":"1994-11-30","article_text":"1. Договором коммерческой концессии могут быть предусмотрены ограничения прав сторон по этому договору, в частности могут быть предусмотрены:\n\nобязательство правообладателя не предоставлять другим лицам аналогичные комплексы исключительных прав для их использования на закрепленной за пользователем территории либо воздерживаться от собственной аналогичной деятельности на этой территории;\n\nобязательство пользователя не конкурировать с правообладателем на территории, на которую распространяется действие договора коммерческой концессии в отношении предпринимательской деятельности, осуществляемой пользователем с использованием принадлежащих правообладателю исключительных прав;\n\nотказ пользователя от получения по договорам коммерческой концессии аналогичных прав у конкурентов (потенциальных конкурентов) правообладателя;\n\nобязательство пользователя реализовывать, в том числе перепродавать, произведенные и (или) закупленные товары, выполнять работы или оказывать услуги с использованием принадлежащих правообладателю исключительных прав по установленным правообладателем ценам, а равно обязательство пользователя не осуществлять реализацию аналогичных товаров, выполнение аналогичных работ или оказание аналогичных услуг с использованием товарных знаков или коммерческих обозначений других правообладателей;\n\nобязательство пользователя продавать товары, выполнять работы или оказывать услуги исключительно в пределах определенной территории;\n\nобязательство пользователя согласовывать с правообладателем место расположения коммерческих помещений, используемых при осуществлении предоставленных по договору исключительных прав, а также их внешнее и внутреннее оформление.\n\n2. Условия договора коммерческой концессии, предусматривающие обязательство пользователя продавать товары, выполнять работы или оказывать услуги исключительно покупателям (заказчикам), имеющим место нахождения, место жительства на определенной договором территории, являются ничтожными.\n\n3. Ограничительные условия могут быть признаны недействительными по требованию антимонопольного органа или иного заинтересованного лица, если эти условия с учетом состояния соответствующего рынка и экономического положения сторон противоречат антимонопольному законодательству.\n\n(Статья в редакции Федерального закона от 18.07.2011 № 216-ФЗ)","article_title":"Статья 1033. Ограничения прав сторон по договору коммерческой концессии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"02595411da1de8cb4568f489d7cfb8425041d53a2b54dd29e2a2b48dfdb314c9"},{"code_id":"GK_RF_2","article_number":"1034","version_date":"1994-11-30","article_text":"Правообладатель несет субсидиарную ответственность по предъявляемым к пользователю требованиям о несоответствии качества товаров (работ, услуг), продаваемых (выполняемых, оказываемых) пользователем по договору коммерческой концессии.\n\nПо требованиям, предъявляемым к пользователю как изготовителю продукции (товаров) правообладателя, правообладатель отвечает солидарно с пользователем.","article_title":"Статья 1034. Ответственность правообладателя по требованиям, предъявляемым к пользователю","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c435f0927a4904445584c5bdf8016dbc6bc214e977dcaec7cc7b3fcfbc027141"},{"code_id":"GK_RF_2","article_number":"1035","version_date":"1994-11-30","article_text":"1. Пользователь, надлежащим образом исполнявший свои обязанности, по истечении срока договора коммерческой концессии имеет преимущественное право на заключение договора на новый срок.\n\nПри заключении договора коммерческой концессии на новый срок условия договора могут быть изменены по соглашению сторон.\n\n2. Если правообладатель отказал пользователю в заключении договора коммерческой концессии на новый срок, но в течение года со дня истечения срока договора с ним заключил с другим лицом договор коммерческой концессии, по которому предоставлены те же права, какие были предоставлены пользователю по прекратившемуся договору, на тех же условиях, пользователь вправе потребовать по своему выбору в суде перевода на себя прав и обязанностей по заключенному договору и возмещения убытков, причиненных отказом возобновить с ним договор коммерческой концессии, или только возмещения таких убытков.\n\n(Статья в редакции Федерального закона от 18.07.2011 № 216-ФЗ)","article_title":"Статья 1035. Преимущественное право пользователя на заключение договора коммерческой концессии на новый срок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a34049ee99af87590a2a7edcc19eac6a7b8e47fa1db8163e8a121b7abec7c86a"},{"code_id":"GK_RF_2","article_number":"1036","version_date":"1994-11-30","article_text":"1. Договор коммерческой концессии может быть изменен в соответствии с правилами главы 29 настоящего Кодекса.\n\n2. Изменение договора коммерческой концессии подлежит государственной регистрации в порядке, установленном пунктом 2 статьи 1028 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 18.12.2006 № 231-ФЗ)","article_title":"Статья 1036. Изменение договора коммерческой концессии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1f7f3e072d09dc87fd19aa41a5162fe73cf541dd19072e9b2e773f78d0222837"},{"code_id":"GK_RF_2","article_number":"1037","version_date":"1994-11-30","article_text":"1. Каждая из сторон договора коммерческой концессии, заключенного без указания срока его действия, во всякое время вправе отказаться от договора, уведомив об этом другую сторону за шесть месяцев, если договором не предусмотрен более продолжительный срок.\n\nКаждая из сторон договора коммерческой концессии, заключенного на определенный срок или без указания срока его действия, во всякое время вправе отказаться от договора, уведомив об этом другую сторону не позднее чем за тридцать дней, если договором предусмотрена возможность его прекращения уплатой денежной суммы, установленной в качестве отступного.\n\n(Пункт в редакции Федерального закона от 18.07.2011 № 216-ФЗ)\n\n11. Правообладатель вправе отказаться от исполнения договора коммерческой концессии полностью или частично в случае:\n\nнарушения пользователем условий договора о качестве производимых товаров, выполняемых работ, оказываемых услуг;\n\nгрубого нарушения пользователем инструкций и указаний правообладателя, направленных на обеспечение соответствия условиям договора характера, способов и условий использования предоставленного комплекса исключительных прав;\n\nнарушения пользователем обязанности выплатить правообладателю вознаграждение в установленный договором срок.\n\nОдносторонний отказ правообладателя от исполнения договора возможен в случае, если пользователь после направления ему правообладателем письменного требования об устранении нарушения не устранил его в разумный срок или вновь совершил такое нарушение в течение одного года с даты направления ему указанного требования.\n\n(Дополнение пунктом - Федеральный закон от 18.07.2011 № 216-ФЗ)","article_title":"Статья 1037. Прекращение договора коммерческой концессии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"066836e9c4855015fad331bbc4c631911d4c160ba5a614bb68c0101c8c7173e5"},{"code_id":"GK_RF_2","article_number":"1038","version_date":"1994-11-30","article_text":"1. Переход к другому лицу какого-либо исключительного права, входящего в предоставленный пользователю комплекс исключительных прав, не является основанием для изменения или расторжения договора коммерческой концессии. Новый правообладатель становится стороной этого договора в части прав и обязанностей, относящихся к перешедшему исключительному праву.\n\n2. В случае смерти правообладателя его права и обязанности по договору коммерческой концессии переходят к наследнику при условии, что он зарегистрирован или в течение шести месяцев со дня открытия наследства зарегистрируется в качестве индивидуального предпринимателя. В противном случае договор прекращается.\n\nОсуществление прав и исполнение обязанностей умершего правообладателя до принятия наследником этих прав и обязанностей или до регистрации наследника в качестве индивидуального предпринимателя осуществляются управляющим, назначаемым нотариусом.","article_title":"Статья 1038. Сохранение договора коммерческой концессии в силе при перемене сторон","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a6e8023424fef7e48a0aac4145c677a2945e0486a76a7035e0bd4954f3a076b"},{"code_id":"GK_RF_2","article_number":"1039","version_date":"1994-11-30","article_text":"В случае изменения правообладателем коммерческого обозначения, входящего в комплекс исключительных прав, предоставленных пользователю по договору коммерческой концессии, этот договор продолжает действовать в отношении нового коммерческого обозначения правообладателя, если пользователь не потребует расторжение договора и возмещение убытков. В случае продолжения действия договора пользователь вправе потребовать соразмерного уменьшения причитающегося правообладателю вознаграждения.\n\n(Статья в редакции Федерального закона от 18.12.2006 № 231-ФЗ)","article_title":"Статья 1039. Последствия изменения коммерческого обозначения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"273825d4ba684e71a1d7b727c5ca5e5aa95654fe5d1591e0d59b30f38668ea21"},{"code_id":"GK_RF_2","article_number":"1040","version_date":"1994-11-30","article_text":"Если в период действия договора коммерческой концессии истек срок действия исключительного права, пользование которым предоставлено по этому договору, либо такое право прекратилось по иному основанию, договор коммерческой концессии продолжает действовать, за исключением положений, относящихся к прекратившемуся праву, а пользователь, если иное не предусмотрено договором, вправе потребовать соразмерного уменьшения причитающегося правообладателю вознаграждения.\n\nВ случае прекращения принадлежащего правообладателю исключительного права на товарный знак, знак обслуживания или на коммерческое обозначение наступают последствия, предусмотренные пунктом 3 статьи 1037 и статьей 1039 настоящего Кодекса. (В редакции Федерального закона от 18.12.2006 № 231-ФЗ)","article_title":"Статья 1040. Последствия прекращения исключительного права, пользование которым предоставлено по договору коммерческой концессии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bbcab84242de4a338394f1bdafd2acccc7596ea8453b9460937bceffbd0f41a7"},{"code_id":"GK_RF_2","article_number":"1041","version_date":"1994-11-30","article_text":"1. По договору простого товарищества (договору о совместной деятельности) двое или несколько лиц (товарищей) обязуются соединить свои вклады и совместно действовать без образования юридического лица для извлечения прибыли или достижения иной не противоречащей закону цели.\n\n2. Сторонами договора простого товарищества, заключаемого для осуществления предпринимательской деятельности, могут быть только индивидуальные предприниматели и (или) коммерческие организации.","article_title":"Статья 1041. Договор простого товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c0f31ada14596e3d2a7f5b9abd24b9ac6ca86bb16a9eeefde2de554a8af75185"},{"code_id":"GK_RF_2","article_number":"1042","version_date":"1994-11-30","article_text":"1. Вкладом товарища признается все то, что он вносит в общее дело, в том числе деньги, иное имущество, профессиональные и иные знания, навыки и умения, а также деловая репутация и деловые связи.\n\n2. Вклады товарищей предполагаются равными по стоимости, если иное не следует из договора простого товарищества или фактических обстоятельств. Денежная оценка вклада товарища производится по соглашен\n\nию между товарищами.","article_title":"Статья 1042. Вклады товарищей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4160be588e3f723a06035bf0e27227fcfa6aa7a76f8d48f24489e48acc537e28"},{"code_id":"GK_RF_2","article_number":"1043","version_date":"1994-11-30","article_text":"1. Внесенное товарищами имущество, которым они обладали на праве собственности, а также произведенная в результате совместной деятельности продукция и полученные от такой деятельности плоды и доходы признаются их общей долевой собственностью, если иное не установлено законом или договором простого товарищества либо не вытекает из существа обязательства.\n\nВнесенное товарищами имущество, которым они обладали по основаниям, отличным от права собственности, используется в интересах всех товарищей и составляет наряду с имуществом, находящимся в их общей собственности, общее имущество товарищей.\n\n2. Ведение бухгалтерского учета общего имущества товарищей может быть поручено ими одному из участвующих в договоре простого товарищества юридических лиц.\n\n3. Пользование общим имуществом товарищей осуществляется по их общему согласию, а при недостижении согласия в порядке, устанавливаемом судом.\n\n4. Обязанности товарищей по содержанию общего имущества и порядок возмещения расходов, связанных с выполнением этих обязанностей, определяются договором простого товарищества.","article_title":"Статья 1043. Общее имущество товарищей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0b3594c34567b368e2709d74c8869f3f0b3621b72fbd98caf9e8c1363c229621"},{"code_id":"GK_RF_2","article_number":"1044","version_date":"1994-11-30","article_text":"1. При ведении общих дел каждый товарищ вправе действовать от имени всех товарищей, если договором простого товарищества не установлено, что ведение дел осуществляется отдельными участниками либо совместно всеми участниками договора простого товарищества.\n\nПри совместном ведении дел для совершения каждой сделки требуется согласие всех товарищей.\n\n2. В отношениях с третьими лицами полномочие товарища совершать сделки от имени всех товарищей удостоверяется доверенностью, выданной ему остальными товарищами, или договором простого товарищества, совершенным в письменной форме.\n\n3. В отношениях с третьими лицами товарищи не могут ссылаться на ограничения прав товарища, совершившего сделку, по ведению общих дел товарищей, за исключением случаев, когда они докажут, что в момент заключения сделки третье лицо знало или должно было знать о наличии таких ограничений.\n\n4. Товарищ, совершивший от имени всех товарищей сделки, в отношении которых его право на ведение общих дел товарищей было ограничено, либо заключивший в интересах всех товарищей сделки от своего имени, может требовать возмещения произведенных им за свой счет расходов, если имелись достаточные основания полагать, что эти сделки были необходимыми в интересах всех товарищей. Товарищи, понесшие вследствие таких сделок убытки, вправе требовать их возмещения.\n\n5. Решения, касающиеся общих дел товарищей, принимаются товарищами по общему согласию, если иное не предусмотрено договором простого товарищества.","article_title":"Статья 1044. Ведение общих дел товарищей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a5056b95ab1d3df5c7711c614197df253fe6eeaf2a3140e7a1b8f2c657015472"},{"code_id":"GK_RF_2","article_number":"1045","version_date":"1994-11-30","article_text":"Каждый товарищ независимо от того, уполномочен ли он вести общие дела товарищей, вправе знакомиться со всей документацией по ведению дел. Отказ от этого права или его ограничение, в том числе по соглашению товарищей, ничтожны.","article_title":"Статья 1045. Право товарища на информацию","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"407c2dd49564bfb72110ed7d135ae182b5b2b558fece01e91d5f7efcf4057541"},{"code_id":"GK_RF_2","article_number":"1046","version_date":"1994-11-30","article_text":"Порядок покрытия расходов и убытков, связанных с совместной деятельностью товарищей, определяется их соглашением. При отсутствии такого соглашения каждый товарищ несет расходы и убытки пропорционально стоимости его вклада в общее дело.\n\nСоглашение, полностью освобождающее кого-либо из товарищей от участия в покрытии общих расходов или убытков, ничтожно.","article_title":"Статья 1046. Общие расходы и убытки товарищей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4f4b017666950ddc2f4a893b0eb13318fbf79d757cd57e76c5d6ab5bb6d5e229"},{"code_id":"GK_RF_2","article_number":"1047","version_date":"1994-11-30","article_text":"1. Если договор простого товарищества не связан с осуществлением его участниками предпринимательской деятельности, каждый товарищ отвечает по общим договорным обязательствам всем своим имуществом пропорционально стоимости его вклада в общее дело.\n\nПо общим обязательствам, возникшим не из договора, товарищи отвечают солидарно.\n\n2. Если договор простого товарищества связан с осуществлением его участниками предпринимательской деятельности, товарищи отвечают солидарно по всем общим обязательствам независимо от оснований их возникновения.","article_title":"Статья 1047. Ответственность товарищей по общим обязательствам","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0e6b22e76abc6082e1f741faf45886996087e85940259afc11e16948b2d62ad0"},{"code_id":"GK_RF_2","article_number":"1048","version_date":"1994-11-30","article_text":"Прибыль, полученная товарищами в результате их совместной деятельности, распределяется пропорционально стоимости вкладов товарищей в общее дело, если иное не предусмотрено договором простого товарищества или иным соглашением товарищей. Соглашение об устранении кого-либо из товарищей от участия в прибыли ничтожно.","article_title":"Статья 1048. Распределение прибыли","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"547f188db5a441965cfecc311ff534c1deacd4bfc0d3b6e7fb289d0dbc8ba6e3"},{"code_id":"GK_RF_2","article_number":"1049","version_date":"1994-11-30","article_text":"Кредитор участника договора простого товарищества вправе предъявить требование о выделе его доли в общем имуществе в соответствии со статьей 255 настоящего Кодекса.","article_title":"Статья 1049. Выдел доли товарища по требованию его кредитора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bdbbd3888e5975eb3e5a4889a5ec2e0b3df4ebcfcabb86739dee173dae0a4538"},{"code_id":"GK_RF_2","article_number":"1050","version_date":"1994-11-30","article_text":"1. Договор простого товарищества прекращается вследствие:\n\nобъявления кого-либо из товарищей недееспособным, ограниченно дееспособным или безвестно отсутствующим, если договором простого товарищества или последующим соглашением не предусмотрено сохранение договора в отношениях между остальными товарищами;\n\nобъявления кого-либо из товарищей несостоятельным (банкротом), за изъятием, указанным в абзаце втором настоящего пункта;\n\nсмерти товарища или ликвидации либо реорганизации участвующего в договоре простого товарищества юридического лица, если договором или последующим соглашением не предусмотрено сохранение договора в отношениях между остальными товарищами либо замещение умершего товарища (ликвидированного или реорганизованного юридического лица) его наследниками (правопреемниками);\n\nотказа кого-либо из товарищей от дальнейшего участия в бессрочном договоре простого товарищества, за изъятием, указанным в абзаце втором настоящего пункта;\n\nрасторжения договора простого товарищества, заключенного с указанием срока, по требованию одного из товарищей в отношениях между ним и остальными товарищами, за изъятием, указанным в абзаце втором настоящего пункта;\n\nистечения срока договора простого товарищества;\n\nвыдела доли товарища по требованию его кредитора, за изъятием, указанным в абзаце втором настоящего пункта.\n\n2. При прекращении договора простого товарищества вещи, переданные в общее владение и (или) пользование товарищей, возвращаются предоставившим их товарищам без вознаграждения, если иное не предусмотрено соглашением сторон.\n\nС момента прекращения договора простого товарищества его участники несут солидарную ответственность по неисполненным общим обязательствам в отношении третьих лиц.\n\nТоварищ, внесший в общую собственность индивидуально определенную вещь, вправе при прекращении договора простого товарищества требовать в судебном порядке возврата ему этой вещи при условии соблюдения интересов остальных товарищей и кредиторов.","article_title":"Статья 1050. Прекращение договора простого товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bfd1f9524741ecbf10e078f8e2e8cb3f823b77817fe75f3a2cd074ea68d38e5f"},{"code_id":"GK_RF_2","article_number":"1051","version_date":"1994-11-30","article_text":"Заявление об отказе товарища от бессрочного договора простого товарищества должно быть сделано им не позднее чем за три месяца до предполагаемого выхода из договора.\n\nСоглашение об ограничении права на отказ от бессрочного договора простого товарищества является ничтожным.","article_title":"Статья 1051. Отказ от бессрочного договора простого товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"945c5144bb5ba5416fc1242c37a382362227258b21bad9e552807cfba8eefd42"},{"code_id":"GK_RF_2","article_number":"1052","version_date":"1994-11-30","article_text":"Наряду с основаниями, указанными в пункте 2 статьи 450 настоящего Кодекса, сторона договора простого товарищества, заключенного с указанием срока или с указанием цели в качестве отменительного условия, вправе требовать расторжения договора в отношениях между собой и остальными товарищами по уважительной причине с возмещением остальным товарищам реального ущерба, причиненного расторжением договора.","article_title":"Статья 1052. Расторжение договора простого товарищества по требованию стороны","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0291cd846750a757a5c4c67c9cae8fdd91c2783f5661ddecbe2b7d2f8c8699f4"},{"code_id":"GK_RF_2","article_number":"1053","version_date":"1994-11-30","article_text":"В случае, когда договор простого товарищества не был прекращен в результате заявления кого-либо из участников об отказе от дальнейшего в нем участия либо расторжения договора по требованию одного из товарищей, лицо, участие которого в договоре прекратилось, отвечает перед третьими лицами по общим обязательствам, возникшим в период его участия в договоре, так, как если бы оно осталось участником договора простого товарищества.","article_title":"Статья 1053. Ответственность товарища, в отношении которого договор простого товарищества расторгнут","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a7a207237e7c8b003ebe97563e1e451c14313b4d2c61a82080e1d458b46bb339"},{"code_id":"GK_RF_2","article_number":"1054","version_date":"1994-11-30","article_text":"1. Договором простого товарищества может быть предусмотрено, что его существование не раскрывается для третьих лиц (негласное товарищество). К такому договору применяются предусмотренные настоящей главой правила о договоре простого товарищества, если иное не предусмотрено настоящей статьей или не вытекает из существа негласного товарищества.\n\n2. В отношениях с третьими лицами каждый из участников негласного товарищества отвечает всем своим имуществом по сделкам, которые он заключил от своего имени в общих интересах товарищей.\n\n3. В отношениях между товарищами обязательства, возникшие в процессе их совместной деятельности, считаются общими.","article_title":"Статья 1054. Негласное товарищество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c6657f8b9f556896c3c7bfbb1e02437db3862eb65932b96f2d9d29ba2abedb34"},{"code_id":"GK_RF_2","article_number":"1055","version_date":"1994-11-30","article_text":"1. Лицо, объявившее публично о выплате денежного вознаграждения или выдаче иной награды (о выплате награды) тому, кто совершит указанное в объявлении правомерное действие в указанный в нем срок, обязано выплатить обещанную награду любому, кто совершил соответствующее действие, в частности отыскал утраченную вещь или сообщил лицу, объявившему о награде, необходимые сведения.\n\n2. Обязанность выплатить награду возникает при условии, что обещание награды позволяет установить, кем она обещана. Лицо, отозвавшееся на обещание, вправе потребовать письменного подтверждения обещания и несет риск последствий непредъявления этого требования, если окажется, что в действительности объявление о награде не было сделано указанным в нем лицом.\n\n3. Если в публичном обещании награды не указан ее размер, он определяется по соглашению с лицом, обещавшим награду, а в случае спора судом.\n\n4. Обязанность выплатить награду возникает независимо от того, совершено ли соответствующее действие в связи со сделанным объявлением или независимо от него.\n\n5. В случаях, когда действие, указанное в объявлении, совершили несколько лиц, право на получение награды приобретает то из них, кто совершил соответствующее действие первым.\n\nЕсли действие, указанное в объявлении, совершено двумя или более лицами и невозможно определить, кто из них совершил соответствующее действие первым, а также в случае, если действие совершено двумя или более лицами одновременно, награда между ними делится поровну или в ином предусмотренном соглашением между ними размере.\n\n6. Если иное не предусмотрено в объявлении о награде и не вытекает из характера указанного в нем действия, соответствие выполненного действия содержащимся в объявлении требованиям определяется лицом, публично обещавшим награду, а в случае спора судом.","article_title":"Статья 1055. Обязанность выплатить награду","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eaf3deeb22ed5ae7c9c875ae0e227c74cf437d2b232f4532c4d762acbde1f41a"},{"code_id":"GK_RF_2","article_number":"1056","version_date":"1994-11-30","article_text":"1. Лицо, объявившее публично о выплате награды, вправе в такой же форме отказаться от данного обещания, кроме случаев, когда в самом объявлении предусмотрена или из него вытекает недопустимость отказа или дан определенный срок для совершения действия, за которое обещана награда, либо к моменту объявления об отказе одно или несколько отозвавшихся лиц уже выполнили указанное в объявлении действие.\n\n2. Отмена публичного обещания награды не освобождает того, кто объявил о награде, от возмещения отозвавшимся лицам расходов, понесенных ими в связи с совершением указанного в объявлении действия, в пределах указанной в объявлении награды.","article_title":"Статья 1056. Отмена публичного обещания награды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ab46989186db042b7f407ada2fc9ab41862760d92809aebeeb68791cd778e8e4"},{"code_id":"GK_RF_2","article_number":"1057","version_date":"1994-11-30","article_text":"1. Лицо, объявившее публично о выплате денежного вознаграждения или выдаче иной награды (о выплате награды) за лучшее выполнение работы или достижение иных результатов (публичный конкурс), должно выплатить (выдать) обусловленную награду тому, кто в соответствии с условиями проведения конкурса признан его победителем.\n\n2. Публичный конкурс должен быть направлен на достижение каких-либо общественно полезных целей.\n\n3. Публичный конкурс может быть открытым, когда предложение организатора конкурса принять в нем участие обращено ко всем желающим путем объявления в печати или иных средствах массовой информации, либо закрытым, когда предложение принять участие в конкурсе направляется определенному кругу лиц по выбору организатора конкурса.\n\nОткрытый конкурс может быть обусловлен предварительной квалификацией его участников, когда организатором конкурса проводится предварительный отбор лиц, пожелавших принять в нем участие.\n\n4. Объявление о публичном конкурсе должно содержать по крайней мере условия, предусматривающие существо задания, критерии и порядок оценки результатов работы или иных достижений, место, срок и порядок их представления, размер и форму награды, а также порядок и сроки объявления результатов конкурса.\n\n5. К публичному конкурсу, содержащему обязательство заключить с победителем конкурса договор, правила, предусмотренные настоящей главой, применяются постольку, поскольку статьями 447 - 449 настоящего Кодекса не предусмотрено иное.","article_title":"Статья 1057. Организация публичного конкурса","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2b61a8dd94e54cd9cea7a9d61bdf2fdc831bc6d9b7b0f2be16140a4ea34267ec"},{"code_id":"GK_RF_2","article_number":"1058","version_date":"1994-11-30","article_text":"1. Лицо, объявившее публичный конкурс, вправе изменить его условия или отменить конкурс только в течение первой половины установленного для представления работ срока.\n\n2. Извещение об изменении условий или отмене конкурса должно быть сделано тем же способом, каким конкурс был объявлен.\n\n3. В случае изменения условий конкурса или его отмены лицо, объявившее о конкурсе, должно возместить расходы, понесенные любым лицом, которое выполнило предусмотренную в объявлении работу до того, как ему стало или должно было стать известно об изменении условий конкурса и о его отмене.\n\nЛицо, объявившее конкурс, освобождается от обязанности возмещения расходов, если докажет, что указанная работа была выполнена не в связи с конкурсом, в частности до объявления о конкурсе, либо заведомо не соответствовала условиям конкурса.\n\n4. Если при изменении условий конкурса или при его отмене были нарушены требования, указанные в пунктах 1 или 2 настоящей статьи, лицо, объявившее конкурс, должно выплатить награду тем, кто выполнил работу, удовлетворяющую указанным в объявлении условиям.","article_title":"Статья 1058. Изменение условий и отмена публичного конкурса","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7dc8e8c786d5d5f84f4e33b22cd3ffef009ae886fdfd60bc799993cf794b26de"},{"code_id":"GK_RF_2","article_number":"1059","version_date":"1994-11-30","article_text":"1. Решение о выплате награды должно быть вынесено и сообщено участникам публичного конкурса в порядке и в сроки, которые установлены в объявлении о конкурсе.\n\n2. Если указанные в объявлении результаты достигнуты в работе, выполненной совместно двумя или более лицами, награда распределяется в соответствии с достигнутым между ними соглашением. В случае, если такое соглашение не будет достигнуто, порядок распределения награды определяется судом.","article_title":"Статья 1059. Решение о выплате награды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9d9a962f11b562ace5f1f08fa4e740bb021cb75ba0760d58264d02ebfd0ed9b7"},{"code_id":"GK_RF_2","article_number":"1060","version_date":"1994-11-30","article_text":"Если предмет публичного конкурса составляет создание произведения науки, литературы или искусства и условиями конкурса не предусмотрено иное, лицо, объявившее публичный конкурс, приобретает преимущественное право на заключение с автором произведения, удостоенного обусловленной награды, договора об использовании произведения с выплатой ему за это соответствующего вознаграждения.","article_title":"Статья 1060. Использование произведений науки, литературы и искусства, удостоенных награды","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"79942a215a703ca4003313edb2efb226229a062c9d433412cb52c71f7fb0f0eb"},{"code_id":"GK_RF_2","article_number":"1061","version_date":"1994-11-30","article_text":"Лицо, объявившее публичный конкурс, обязано возвратить участникам конкурса работы, не удостоенные награды, если иное не предусмотрено объявлением о конкурсе и не вытекает из характера выполненной работы.","article_title":"Статья 1061. Возврат участникам публичного конкурса представленных работ","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"677aa429157fbec010e65d019bc8cb80598a7ecc28d10a90da38cee3d4954664"},{"code_id":"GK_RF_2","article_number":"1062","version_date":"1994-11-30","article_text":"Требования, связанные с участием граждан в указанных в настоящем пункте сделках, подлежат судебной защите только при условии их заключения на бирже, а также в иных случаях, предусмотренных законом. (В редакции Федерального закона от 29.12.2014 № 460-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 26.01.2007 № 5-ФЗ)","article_title":"Статья 1062. Требования, связанные с организацией игр и пари и участием в них","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7da6e716d8c4dbaf8c73e9f8b6883439c37a3d680d6d40733327cc18e19e3596"},{"code_id":"GK_RF_2","article_number":"1063","version_date":"1994-11-30","article_text":"В случае отказа организатора игр от их проведения в установленный срок участники игр вправе требовать от их организатора возмещения понесенного из-за отмены игр или переноса их срока реального ущерба.\n\nа лотереи, организатора игр. (В редакции Федерального закона от 28.12.2013 № 416-ФЗ)","article_title":"Статья 1063. Проведение лотерей, тотализаторов и иных игр государством и муниципальными образованиями или по их разрешению","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c955698d7148031b0fe5828f9bf6bb54ba9b22714f4e0b1a7d385ab008765452"},{"code_id":"GK_RF_2","article_number":"1064","version_date":"1994-11-30","article_text":"1. Вред, причиненный личности или имуществу гражданина, а также вред, причиненный имуществу юридического лица, подлежит возмещению в полном объеме лицом, причинившим вред.\n\nЗаконом обязанность возмещения вреда может быть возложена на лицо, не являющееся причинителем вреда.\n\nЗаконом или договором может быть установлена обязанность причинителя вреда выплатить потерпевшим компенсацию сверх возмещения вреда. Законом может быть установлена обязанность лица, не являющегося причинителем вреда, выплатить потерпевшим компенсацию сверх возмещения вреда. (В редакции Федерального закона от 28.11.2011 № 337-ФЗ)\n\n2. Лицо, причинившее вред, освобождается от возмещения вреда, если докажет, что вред причинен не по его вине. Законом может быть предусмотрено возмещение вреда и при отсутствии вины причинителя вреда.\n\n3. Вред, причиненный правомерными действиями, подлежит возмещению в случаях, предусмотренных законом.\n\nВ возмещении вреда может быть отказано, если вред причинен по просьбе или с согласия потерпевшего, а действия причинителя вреда не нарушают нравственные принципы общества.","article_title":"Статья 1064. Общие основания ответственности за причинение вреда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77eee7c5923e0ce160a8c17bad837b80af877badd6105efb053f1b942260f045"},{"code_id":"GK_RF_2","article_number":"1065","version_date":"1994-11-30","article_text":"1. Опасность причинения вреда в будущем может явиться основанием к иску о запрещении деятельности, создающей такую опасность.\n\n2. Если причиненный вред является последствием эксплуатации предприятия, сооружения либо иной производственной деятельности, которая продолжает причинять вред или угрожает новым вредом, суд вправе обязать ответчика, помимо возмещения вреда, приостановить или прекратить соответствующую деятельность.\n\nСуд может отказать в иске о приостановлении либо прекращении соответствующей деятельности лишь в случае, если ее приостановление либо прекращение противоречит общественным интересам. Отказ в приостановлении либо прекращении такой деятельности не лишает потерпевших права на возмещение причиненного этой деятельностью вреда.","article_title":"Статья 1065. Предупреждение причинения вреда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6322958f3da952c12fe96c1ab188093e236e54ce269cc01721f0b61d73732553"},{"code_id":"GK_RF_2","article_number":"1066","version_date":"1994-11-30","article_text":"Не подлежит возмещению вред, причиненный в состоянии необходимой обороны, если при этом не были превышены ее пределы.","article_title":"Статья 1066. Причинение вреда в состоянии необходимой обороны","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5a0462094bed366d42eaf8b3e6a612ef4dd42916133731ac1eb923d08f386fa2"},{"code_id":"GK_RF_2","article_number":"1067","version_date":"1994-11-30","article_text":"Вред, причиненный в состоянии крайней необходимости, то есть для устранения опасности, угрожающей самому причинителю вреда или другим лицам, если эта опасность при данных обстоятельствах не могла быть устранена иными средствами, должен быть возмещен лицом, причинившим вред.\n\nУчитывая обстоятельства, при которых был причинен такой вред, суд может возложить обязанность его возмещения на третье лицо, в интересах которого действовал причинивший вред, либо освободить от возмещения вреда полностью или частично как это третье лицо, так и причинившего вред.","article_title":"Статья 1067. Причинение вреда в состоянии крайней необходимости","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c0d28b562836a00788509e4ebbaa274b531e5f20fb2d0ae5c2ebec476bf38a4d"},{"code_id":"GK_RF_2","article_number":"1068","version_date":"1994-11-30","article_text":"1. Юридическое лицо либо гражданин возмещает вред, причиненный его работником при исполнении трудовых (служебных, должностных) обязанностей.\n\nПрименительно к правилам, предусмотренным настоящей главой, работниками признаются граждане, выполняющие работу на основании трудового договора (контракта), а также граждане, выполняющие работу по гражданско-правовому договору, если при этом они действовали или должны были действовать по заданию соответствующего юридического лица или гражданина и под его контролем за безопасным ведением работ.\n\n2. Хозяйственные товарищества и производственные кооперативы возмещают вред, причиненный их участниками (членами) при осуществлении последними предпринимательской, производственной или иной деятельности товарищества или кооператива.","article_title":"Статья 1068. Ответственность юридического лица или гражданина за вред, причиненный его работником","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dc40b80efbbfeff49dd263af816850a6eb15c04e37c41f6ac2b61edc1aed011b"},{"code_id":"GK_RF_2","article_number":"1069","version_date":"1994-11-30","article_text":"Вред, причиненный гражданину или юридическому лицу в результате незаконных действий (бездействия) государственных органов, органов местного самоуправления либо должностных лиц этих органов, в том числе в результате издания не соответствующего закону или иному правовому акту акта государственного органа или органа местного самоуправления, подлежит возмещению. Вред возмещается за счет соответственно казны Российской Федерации, казны субъекта Российской Федерации или казны муниципального образования.","article_title":"Статья 1069. Ответственность за вред, причиненный государственными органами, органами местного самоуправления, а также их должностными лицами","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5190bbd96cfe828f8316887ab35dfb3456d1fff5dda0bdccc8e5d67074005e31"},{"code_id":"GK_RF_2","article_number":"1071","version_date":"1994-11-30","article_text":"В случаях, когда в соответствии с настоящим Кодексом или другими законами причиненный вред подлежит возмещению за счет казны Российской Федерации, казны субъекта Российской Федерации или казны муниципального образования, от имени казны выступают соответствующие финансовые органы, если в соответствии с пунктом 3 статьи 125 настоящего Кодекса эта обязанность не возложена на другой орган, юридическое лицо или гражданина.","article_title":"Статья 1071. Органы и лица, выступающие от имени казны при возмещении вреда за ее счет","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d9e5948c5f52b51e7a92f84826a64522d45f69852b78bb8beca68e8f150f9727"},{"code_id":"GK_RF_2","article_number":"1072","version_date":"1994-11-30","article_text":"Юридическое лицо или гражданин, застраховавшие свою ответственность в порядке добровольного или обязательного страхования в пользу потерпевшего (статья 931, пункт 1 статьи 935), в случае, когда страховое возмещение недостаточно для того, чтобы полностью возместить причиненный вред, возмещают разницу между страховым возмещением и фактическим размером ущерба.","article_title":"Статья 1072. Возмещение вреда лицом, застраховавшим свою ответственность","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3b4c94da0e0cc6e457caf5754d6c0c21e5212189b5634ba9c699936107c8b1d0"},{"code_id":"GK_RF_2","article_number":"1073","version_date":"1994-11-30","article_text":"1. За вред, причиненный несовершеннолетним, не достигшим четырнадцати лет (малолетним), отвечают его родители (усыновители) или опекуны, если не докажут, что вред возник не по их вине.\n\nЕсли родители (усыновители), опекуны либо другие граждане, указанные в пункте 3 настоящей статьи, умерли или не имеют достаточных средств для возмещения вреда, причиненного жизни или здоровью потерпевшего, а сам причинитель вреда, ставший полностью дееспособным, обладает такими средствами, суд с учетом имущественного положения потерпевшего и причинителя вреда, а также других обстоятельств вправе принять решение о возмещении вреда полностью или частично за счет самого причинителя вреда.","article_title":"Статья 1073. Ответственность за вред, причиненный несовершеннолетними в возрасте до четырнадцати лет","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a6c5be65ce78082750a3621b7dc9bfd3c7653d89c9ce3d29956b346ab83bda3c"},{"code_id":"GK_RF_2","article_number":"1074","version_date":"1994-11-30","article_text":"1. Несовершеннолетние в возрасте от четырнадцати до восемнадцати лет самостоятельно несут ответственность за причиненный вред на общих основаниях.\n\n2. В случае, когда у несовершеннолетнего в возрасте от четырнадцати до восемнадцати лет нет доходов или иного имущества, достаточных для возмещения вреда, вред должен быть возмещен полностью или в недостающей части его родителями (усыновителями) или попечителем, если они не докажут, что вред возник не по их вине.\n\nЕсли несовершеннолетний гражданин в возрасте от четырнадцати до восемнадцати лет, оставшийся без попечения родителей, был помещен под надзор в организацию для детей-сирот и детей, оставшихся без попечения родителей (статья 1551 Семейного кодекса Российской Федерации), эта организация обязана возместить вред полностью или в недостающей части, если не докажет, что вред возник не по ее вине. (В редакции Федерального закона от 24.04.2008 № 49-ФЗ)","article_title":"Статья 1074. Ответственность за вред, причиненный несовершеннолетними в возрасте от четырнадцати до восемнадцати лет","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40e15bb49a7329b41a9f8fcabbd7746e50adc9359ca157909ef0bc77956d6cfe"},{"code_id":"GK_RF_2","article_number":"1075","version_date":"1994-11-30","article_text":"На родителя, лишенного родительских прав, суд может возложить ответственность за вред, причиненный его несовершеннолетним ребенком в течение трех лет после лишения родителя родительских прав, если поведение ребенка, повлекшее причинение вреда, явилось следствием ненадлежащего осуществления родительских обязанностей.","article_title":"Статья 1075. Ответственность родителей, лишенных родительских прав, за вред, причиненный несовершеннолетними","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0533c646c71354e8664a0da95d6df5532073b0531cb25e59c57928d46951e1ba"},{"code_id":"GK_RF_2","article_number":"1076","version_date":"1994-11-30","article_text":"1. Вред, причиненный гражданином, признанным недееспособным, возмещают его опекун или организация, обязанная осуществлять за ним надзор, если они не докажут, что вред возник не по их вине.\n\n2. Обязанность опекуна или организации, обязанной осуществлять надзор по возмещению вреда, причиненного гражданином, признанным недееспособным, не прекращается в случае последующего признания его дееспособным.\n\n3. Если опекун умер либо не имеет достаточных средств для возмещения вреда, причиненного жизни или здоровью потерпевшего, а сам причинитель вреда обладает такими средствами, суд с учетом имущественного положения потерпевшего и причинителя вреда, а также других обстоятельств вправе принять решение о возмещении вреда полностью или частично за счет самого причинителя вреда.","article_title":"Статья 1076. Ответственность за вред, причиненный гражданином, признанным недееспособным","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5c29f1cc210fd38ccecb18c136181759f4ad1c86be2ad8fd0e48972939a5f211"},{"code_id":"GK_RF_2","article_number":"1077","version_date":"1994-11-30","article_text":"Вред, причиненный гражданином, ограниченным в дееспособности вследствие злоупотребления спиртными напитками или наркотическими средствами, возмещается самим причинителем вреда.","article_title":"Статья 1077. Ответственность за вред, причиненный гражданином, признанным ограниченно дееспособным","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"19c9765640578ee0c3cb7f3f707f9b545e10ec467aeaf5cfc2b351991943419e"},{"code_id":"GK_RF_2","article_number":"1078","version_date":"1994-11-30","article_text":"1. Дееспособный гражданин или несовершеннолетний в возрасте от четырнадцати до восемнадцати лет, причинивший вред в таком состоянии, когда он не мог понимать значения своих действий или руководить ими, не отвечает за причиненный им вред.\n\nЕсли вред причинен жизни или здоровью потерпевшего, суд может с учетом имущественного положения потерпевшего и причинителя вреда, а также других обстоятельств возложить обязанность по возмещению вреда полностью или частично на причинителя вреда.\n\n2. Причинитель вреда не освобождается от ответственности, если сам привел себя в состояние, в котором не мог понимать значения своих действий или руководить ими, употреблением спиртных напитков, наркотических средств или иным способом.\n\n3. Если вред причинен лицом, которое не могло понимать значения своих действий или руководить ими вследствие психического расстройства, обязанность возместить вред может быть возложена судом на проживающих совместно с этим лицом его трудоспособных супруга, родителей, совершеннолетних детей, которые знали о психическом расстройстве причинителя вреда, но не ставили вопрос о признании его недееспособным.","article_title":"Статья 1078. Ответственность за вред, причиненный гражданином, не способным понимать значения своих действий","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"649486a5b5d6243a463feb315b670abc95753a7b50b0efbf4718078e03691835"},{"code_id":"GK_RF_2","article_number":"1079","version_date":"1994-11-30","article_text":"1. Юридические лица и граждане, деятельность которых связана с повышенной опасностью для окружающих (использование транспортных средств, механизмов, электрической энергии высокого напряжения, атомной энергии, взрывчатых веществ, сильнодействующих ядов и т.п.; осуществление строительной и иной, связанной с нею деятельности и др.), обязаны возместить вред, причиненный источником повышенной опасности, если не докажут, что вред возник вследствие непреодолимой силы или умысла потерпевшего. Владелец источника повышенной опасности может быть освобожден судом от ответственности полностью или частично также по основаниям, предусмотренным пунктами 2 и 3 статьи 1083 настоящего Кодекса.\n\nОбязанность возмещения вреда возлагается на юридическое лицо или гражданина, которые владеют источником повышенной опасности на праве собственности, праве хозяйственного ведения или праве оперативного управления либо на ином законном основании (на праве аренды, по доверенности на право управления транспортным средством, в силу распоряжения соответствующего органа о передаче ему источника повышенной опасности и т.п.).\n\n2. Владелец источника повышенной опасности не отвечает за вред, причиненный этим источником, если докажет, что источник выбыл из его обладания в результате противоправных действий других лиц. Ответственность за вред, причиненный источником повышенной опасности, в таких случаях несут лица, противоправно завладевшие источником. При наличии вины владельца источника повышенной опасности в противоправном изъятии этого источника из его обладания ответственность может быть возложена как на владельца, так и на лицо, противоправно завладевшее источником повышенной опасности.\n\n3. Владельцы источников повышенной опасности солидарно несут ответственность за вред, причиненный в результате взаимодействия этих источников (столкновения транспортных средств и т.п.) третьим лицам по основаниям, предусмотренным пунктом 1 настоящей статьи.\n\nВред, причиненный в результате взаимодействия источников повышенной опасности их владельцам, возмещается на общих основаниях (статья 1064).","article_title":"Статья 1079. Ответственность за вред, причиненный деятельностью, создающей повышенную опасность для окружающих","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f87889f5258adbd8a858e08408c2b2c33ef243c3388787d7d06ac1b97d8504bf"},{"code_id":"GK_RF_2","article_number":"1080","version_date":"1994-11-30","article_text":"Лица, совместно причинившие вред, отвечают перед потерпевшим солидарно.\n\nПо заявлению потерпевшего и в его интересах суд вправе возложить на лиц, совместно причинивших вред, ответственность в долях, определив их применительно к правилам, предусмотренным пунктом 2 статьи 1081 настоящего Кодекса.\n\nЛицо, неправомерно завладевшее чужим имуществом, которое в дальнейшем было повреждено или утрачено вследствие действий другого лица, действовавшего независимо от первого лица, отвечает за причиненный вред. Указанное правило не освобождает непосредственного причинителя вреда от возмещения вреда. (Дополнение частью - Федеральный закон от 29.07.2018 № 225-ФЗ)","article_title":"Статья 1080. Ответственность за совместно причиненный вред","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"382aff8b8c7ac6c9bdcbe1445d6a5aaedf0188444bf2c6430c06e7f2e018db63"},{"code_id":"GK_RF_2","article_number":"1081","version_date":"1994-11-30","article_text":"1. Лицо, возместившее вред, причиненный другим лицом (работником при исполнении им служебных, должностных или иных трудовых обязанностей, лицом, управляющим транспортным средством, и т.п.), имеет право обратного требования (регресса) к этому лицу в размере выплаченного возмещения, если иной размер не установлен законом.\n\n2. Причинитель вреда, возместивший совместно причиненный вред, вправе требовать с каждого из других причинителей вреда долю выплаченного потерпевшему возмещения в размере, соответствующем степени вины этого причинителя вреда. При невозможности определить степень вины доли признаются равными.","article_title":"Статья 1081. Право регресса к лицу, причинившему вред","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c8f10c2aa679d768fa87529e7290b8d7ff5c70c76fc2e8fc08ee65ae70c538a1"},{"code_id":"GK_RF_2","article_number":"1082","version_date":"1994-11-30","article_text":"Удовлетворяя требование о возмещении вреда, суд в соответствии с обстоятельствами дела обязывает лицо, ответственное за причинение вреда, возместить вред в натуре (предоставить вещь того же рода и качества, исправить поврежденную вещь и т.п.) или возместить причиненные убытки (пункт 2 статьи 15).","article_title":"Статья 1082. Способы возмещения вреда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a4c703c3640407cd15ce679f2a66bc0557cd2def7f6914b70402a74bdedbc533"},{"code_id":"GK_RF_2","article_number":"1083","version_date":"1994-11-30","article_text":"1. Вред, возникший вследствие умысла потерпевшего, возмещению не подлежит.\n\n2. Если грубая неосторожность самого потерпевшего содействовала возникновению или увеличению вреда, в зависимости от степени вины потерпевшего и причинителя вреда размер возмещения должен быть уменьшен.\n\nПри грубой неосторожности потерпевшего и отсутствии вины причинителя вреда в случаях, когда его ответственность наступает независимо от вины, размер возмещения должен быть уменьшен или в возмещении вреда может быть отказано, если законом не предусмотрено иное. При причинении вреда жизни или здоровью гражданина отказ в возмещении вреда не допускается.\n\nВина потерпевшего не учитывается при возмещении дополнительных расходов (пункт 1 статьи 1085), при возмещении вреда в связи со смертью кормильца (статья 1089), а также при возмещении расходов на погребение (статья 1094).\n\n3. Суд может уменьшить размер возмещения вреда, причиненного гражданином, с учетом его имущественного положения, за исключением случаев, когда вред причинен действиями, совершенными умышленно.","article_title":"Статья 1083. Учет вины потерпевшего и имущественного положения лица, причинившего вред","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1caab0bbaa25dd4c1b04e972951a2e8891dd20556df880cdb7093d78653f9a4e"},{"code_id":"GK_RF_2","article_number":"1084","version_date":"1994-11-30","article_text":"изни или здоровью гражданина при исполнении договорных либо иных обязательств\n\nВред, причиненный жизни или здоровью гражданина при исполнении договорных обязательств, а также при исполнении обязанностей военной службы, службы в полиции и других соответствующих обязанностей возмещается по правилам, предусмотренным настоящей главой, если законом или договором не предусмотрен более высокий размер ответственности. (В редакции Федерального закона от 07.02.2011 № 4-ФЗ)","article_title":"Статья 1084. Возмещение вреда, причиненного ж","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e329d7bd4389cd621427163ea76cd0fef7821c91f0a72855234f2732d786c93b"},{"code_id":"GK_RF_2","article_number":"1085","version_date":"1994-11-30","article_text":"1. При причинении гражданину увечья или ином повреждении его здоровья возмещению подлежит утраченный потерпевшим заработок (доход), который он имел либо определенно мог иметь, а также дополнительно понесенные расходы, вызванные повреждением здоровья, в том числе расходы на лечение, дополнительное питание, приобретение лекарств, протезирование, посторонний уход, санаторно-курортное лечение, приобретение специальных транспортных средств, подготовку к другой профессии, если установлено, что потерпевший нуждается в этих видах помощи и ухода и не имеет права на их бесплатное получение.\n\n2. При определении утраченного заработка (дохода) пенсия по инвалидности, назначенная потерпевшему в связи с увечьем или иным повреждением здоровья, а равно другие пенсии, пособия и иные подобные выплаты, назначенные как до, так и после причинения вреда здоровью, не принимаются во внимание и не влекут уменьшения размера возмещения вреда (не засчитываются в счет возмещения вреда). В счет возмещения вреда не засчитывается также заработок (доход), получаемый потерпевшим после повреждения здоровья.\n\n3. Объем и размер возмещения вреда, причитающегося потерпевшему в соответствии с настоящей статьей, могут быть увеличены законом или договором.","article_title":"Статья 1085. Объем и характер возмещения вреда, причиненного повреждением здоровья","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2b346bd196eb73cb92be3b9bf65f780db539fe55dd589336d6b8774d750d361a"}]$law7d0030$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
